function rarityRoll(n=Math.random()){return n<.6?'Common':n<.9?'Uncommon':n<.99?'Rare':'Epic'}
function rarityColor(r){return {Common:'#9ca3af',Uncommon:'#22c55e',Rare:'#3b82f6',Epic:'#a855f7'}[r]||'inherit'}
function addLoot(name,rarity){const id='loot:'+rarity+':'+name;let item=s.inventory.find(i=>i.id===id);if(item)item.quantity=(item.quantity||1)+1;else s.inventory.push({id,name,rarity,quantity:1});return {id,name,rarity}}
