function monsterMoves(name){const custom={"Green Slime":[["Jump","light",70],["Slime Spit","light",30]],"Blue Slime":[["Bounce","light",50],["Water Shot","light",30],["Harden","guard",20]],"Wild Wolf":[["Bite","light",50],["Pounce","rush",30,25],["Maul","heavy",20]],"Dire Wolf":[["Rend","light",45],["Lunge","rush",30,35],["Savage Bite","heavy",25]],"Slime King":[["Body Slam","light",25],["Triple Spit","light",40],["Crushing Bounce","heavy",20],["Compress","guard",15]],"Acid Slime":[["Acid Splash","light",50],["Corrosive Slap","rush",30,30],["Recoil","guard",20]],"Grey Wolf":[["Snap","light",50],["Shoulder Charge","rush",30,35],["Brace","guard",20]],"Black Wolf":[["Shadow Bite","light",45],["Ambush","rush",35,40],["Ravage","heavy",20]],"Alpha Wolf":[["Bite","light",45],["Pounce","rush",25,30],["Howl","summon",30]],"Fenrir":[["Frost Bite","light",35],["Glacial Pounce","rush",25,50],["Winter's Wrath","heavy",25],["Ice Guard","guard",15]]};return custom[name]||[['light','light',40],['rush','rush',20,100],['heavy','heavy',20],['guard','guard',20]]}
