const identity=`<section class="panel character-sheet acodex-hub rustic-sheet"><div class="rustic-heading"><span class="sheet-gold">✦ ${s.character.gold} Gold</span><small>THE GUILD ARCHIVES</small><h2>Adventurer’s Codex</h2></div><div class="codex-hero"><div class="rustic-portrait">${portrait}<button class="btn ghost" onclick="editCharacterProfile()">Edit profile</button></div><div class="codex-identity"><div class="rustic-name"><span class="rank-insignia">${esc(s.character.rank)}<small>RANK</small></span><div><h2>${esc(s.character.name||'Adventurer')}</h2><small>Level ${s.character.level} · Adventurer</small></div></div><div class="between"><span>Health</span><b>${sheetHp}/${sheetMaxHp}</b></div><div class="codex-track"><i style="width:${sheetHp/sheetMaxHp*100}%;background:#a74c46"></i></div><div class="between"><span>Experience</span><b>${formatXp(levelXp)}/100</b></div><div class="codex-track"><i style="width:${formatXp(levelXp)}%;background:#b49a62"></i></div><div class="between"><span>Rank XP</span><b>${formatXp(rankXp())}/100</b></div><div class="codex-track"><i style="width:${formatXp(rankXp())}%;background:#668b71"></i></div><small>Class: Unassigned</small></div></div></section>`;
const tiles=`<div class="rustic-tiles">${[['stats','Stats','stats'],['skills','Skills','skills'],['equipment','Equipment','equipment'],['inventory','Inventory','inventory']].map(([key,label,icon])=>`<button onclick="setCharacterSection('${key}')">${rusticIcon(icon)}<strong>${label}</strong></button>`).join('')}</div>`;
let content='';
if(characterSection==='status')content=`<section class="rustic-attributes"><h3>— Attributes —</h3><div class="rustic-attr-grid">${attrs.map(([label,key])=>`<button onclick="setCharacterSection('stats')">${rusticIcon(key)}<small>${({strength:'STR',dexterity:'DEX',constitution:'CON',intelligence:'INT'})[key]}</small><b>${attributeLevel(key)}</b><span class="rustic-xp"><i style="width:${formatXp((s.character[key+'Xp']||0)%100)}%"></i></span><small>${formatXp((s.character[key+'Xp']||0)%100)}/100</small></button>`).join('')}</div></section>${tiles}<button class="btn gold rustic-guild" onclick="go('guild')" ${battle?'disabled':''}>${rusticIcon('strength')} Visit the Guild</button><div class="rustic-destinations"><button onclick="go('world')">${rusticScene(false)}<strong>World Map</strong></button><button onclick="go('home')">${rusticScene(true)}<strong>Home</strong></button></div>`;
if(characterSection==='stats')content=`<section class="panel codex-attributes"><div class="between"><h2>Attributes</h2><button class="btn ghost" onclick="setCharacterSection('status')">← Status</button></div>${attrs.map(([label,key])=>{const color={strength:'#e18b78',dexterity:'#8ac79d',constitution:'#d5b578',intelligence:'#9aaff0'}[key],xp=(s.character[key+'Xp']||0)%100;return `<div class="codex-attr" style="--stat-color:${color}"><span class="codex-stat-icon">${{strength:'⚔',dexterity:'➶',constitution:'♥',intelligence:'✦'}[key]}</span><div class="codex-stat-body"><div class="between"><b>${label}</b><small>${formatXp(xp)}/100 XP</small></div><div class="codex-track"><i style="width:${formatXp(xp)}%"></i></div></div><strong>${attributeLevel(key)}</strong><button class="help-dot" onclick="toggleQuestHelp('home-${key}',this)" aria-expanded="false">?</button></div><div class="quest-tip" id="home-${key}">${attributeHelp[key]}</div>`}).join('')}</section>`;
if(characterSection==='skills')content=`<section class="panel"><div class="between"><h2>Skills</h2><button class="btn ghost" onclick="setCharacterSection('status')">← Status</button></div><p class="muted">No skills learned yet. Skills and unlock progression will be added here.</p></section>`;
if(characterSection==='inventory')content='<section class="panel"><h2>Inventory</h2><button class="btn ghost" onclick="setCharacterSection(\'status\')">← Status</button>'+inventoryTabs()+inventoryEntries().filter(i=>inventoryCategory(i)===inventoryTab).map(i=>{const g=gearInfo(i);return '<div class="item"><div>'+inventoryItemSprite(i)+'<b style="color:'+(i.rarity?rarityColor(i.rarity):'inherit')+'">'+esc(i.name)+(i.quantity?' ×'+i.quantity:'')+'</b><p>'+(i.bonus?'+'+i.bonus+' '+attributeName(i.stat):g?'Beginner equipment':i.chestKind?'Contains random '+(i.chestKind==='Tier'?i.rarity:'Uncommon')+' equipment':'Owned item')+'</p>'+enchantmentText(i)+'</div>'+(g?'<button class="btn gold" onclick="equipGear(\''+i.id+'\',\''+g.slot+'\')" '+(equippedGear(g.slot)===i?'disabled':'')+'>'+(equippedGear(g.slot)===i?'Equipped':'Equip')+'</button>':i.chestKind?'<button class="btn gold" onclick="openGearChest(\''+i.id+'\')">Open</button>':'')+'</div>'}).join('')+(inventoryEntries().some(i=>inventoryCategory(i)===inventoryTab)?'':'<p class="muted">No items in this category.</p>')+'</section>';
if(characterSection==='equipment')content='<section class="panel"><h2>Equipment</h2><button class="btn ghost" onclick="setCharacterSection(\'status\')">← Status</button>'+['weapon','helm','chest','pants','gloves','boots'].map(slot=>{const i=equippedGear(slot);return '<div class="item"><div><b>'+slot.toUpperCase()+'</b><p>'+esc(i?.name||'Empty')+(i?.bonus?' · +'+i.bonus+' '+attributeName(i.stat):'')+'</p>'+enchantmentText(i)+'</div>'+(i?'<button class="btn ghost" onclick="equipGear(\'\',\''+slot+'\')">Unequip</button>':'')+'</div>'}).join('')+'<p>'+repDamage()+' damage / rep · '+attributeName(combatAttribute())+(magicAttackBonus()?' · +'+magicAttackBonus()+' magic damage / attack':'')+'</p></section>';
if(characterSection==='profile')content=profilePanel();
if(characterSection==='settings')content=`<button class="btn ghost" onclick="setCharacterSection('status')">← Status</button><section class="panel"><h2>Save & Portability</h2><p class="muted">Progress is stored in this browser on this device. Export a backup regularly, especially before clearing browser data.</p><div class="actions"><button class="btn" onclick="backup()">Export backup</button><button class="btn ghost" onclick="document.querySelector('#file').click()">Import backup</button><input id="file" type="file" accept="application/json" hidden onchange="restore(event)"></div></section>`;
